import software.amazon.awscdk.services.ec2.SecurityGroup;
import software.amazon.awscdk.services.ec2.Vpc;
import software.amazon.awscdk.services.ec2.Peer;
import software.amazon.awscdk.services.ec2.Port;
import software.amazon.awscdk.Stack;
import software.amazon.awscdk.StackProps;
import software.constructs.Construct;
import io.github.cdklabs.cdknag.NagSuppressions;


public class CdkTestStack extends Stack {
    public CdkTestStack(Construct scope, String id) {
        this(scope, id, null);
    }

    public CdkTestStack(Construct scope, String id, StackProps props) {
        super(scope, id, props);
        SecurityGroup test = SecurityGroup.Builder.create(this, "test")
                .vpc(new Vpc(this, "vpc"))
                .build();
        test.addIngressRule(Peer.anyIpv4(), Port.allTraffic());
        NagSuppressions.addResourceSuppressions(test, List.of(NagPackSuppression.builder().id("AwsSolutions-EC23").reason("lorem ipsum").build()));
    }
}

