using Amazon.CDK.AWS.IAM;
using Amazon.CDK;
using Constructs;
using Cdklabs.CdkNag;

class CdkTestStack : Stack
{
    public CdkTestStack(Construct scope, string id, StackProps? props=null) : base(scope, id, props)
    {
        var user = new User(this, "rUser");
        user.AddToPolicy(
        new PolicyStatement(new PolicyStatementProps {
            Actions = new [] { "s3:PutObject" },
            Resources = new [] { "arn:aws:s3:::bucket_name/*" }
        }));
        // Enable adding suppressions to child constructs
        NagSuppressions.AddResourceSuppressions(user, new [] { new NagPackSuppression {
            Id = "AwsSolutions-IAM5",
            Reason = "lorem ipsum",
            AppliesTo = new [] { "Resource::arn:aws:s3:::bucket_name/*" }
        } }, true);
    }
}

