using Amazon.CDK;
using Amazon.CDK.AWS.CodeCommit;
using Amazon.CDK.Pipelines;
using Cdklabs.CdkNag;
using Constructs;

class ExamplePipeline : Stack
{
    public ExamplePipeline(Construct scope, string id, StackProps? props=null) : base(scope, id, props)
    {

        var exampleSynth = new ShellStep("ExampleSynth", new ShellStepProps {
            Commands = new [] { "yarn build --frozen-lockfile" },
            Input = CodePipelineSource.CodeCommit(
            new Repository(this, "ExampleRepo", new RepositoryProps { RepositoryName = "ExampleRepo" }), "main")
        });

        var ExamplePipeline = new CodePipeline(this, "ExamplePipeline", new CodePipelineProps {
            Synth = exampleSynth
        });

        // Force the pipeline construct creation forward before applying suppressions.
        // @See https://github.com/aws/aws-cdk/issues/18440
        ExamplePipeline.BuildPipeline();

        // The path suppression will error if you comment out "ExamplePipeline.buildPipeline();""
        NagSuppressions.AddResourceSuppressionsByPath(this, "/example-cdk-pipeline/ExamplePipeline/Pipeline/ArtifactsBucket/Resource", new [] { new NagPackSuppression {
            Id = "AwsSolutions-S1",
            Reason = "Because I said so"
        } });
    }
}

