import software.amazon.awscdk.Stack;
import software.amazon.awscdk.StackProps;
import software.amazon.awscdk.services.codecommit.Repository;
import software.amazon.awscdk.pipelines.CodePipeline;
import software.amazon.awscdk.pipelines.CodePipelineSource;
import software.amazon.awscdk.pipelines.ShellStep;
import io.github.cdklabs.cdknag.NagSuppressions;
import software.constructs.Construct;


public class ExamplePipeline extends Stack {
    public ExamplePipeline(Construct scope, String id) {
        this(scope, id, null);
    }

    public ExamplePipeline(Construct scope, String id, StackProps props) {
        super(scope, id, props);

        ShellStep exampleSynth = ShellStep.Builder.create("ExampleSynth")
                .commands(List.of("yarn build --frozen-lockfile"))
                .input(CodePipelineSource.codeCommit(
                Repository.Builder.create(this, "ExampleRepo").repositoryName("ExampleRepo").build(), "main"))
                .build();

        CodePipeline ExamplePipeline = CodePipeline.Builder.create(this, "ExamplePipeline")
                .synth(exampleSynth)
                .build();

        // Force the pipeline construct creation forward before applying suppressions.
        // @See https://github.com/aws/aws-cdk/issues/18440
        ExamplePipeline.buildPipeline();

        // The path suppression will error if you comment out "ExamplePipeline.buildPipeline();""
        NagSuppressions.addResourceSuppressionsByPath(this, "/example-cdk-pipeline/ExamplePipeline/Pipeline/ArtifactsBucket/Resource", List.of(NagPackSuppression.builder()
                .id("AwsSolutions-S1")
                .reason("Because I said so")
                .build()));
    }
}

