using Amazon.CDK.AWS.EC2;
using Amazon.CDK;
using Constructs;
using Cdklabs.CdkNag;

class CdkTestStack : Stack
{
    public CdkTestStack(Construct scope, string id, StackProps? props=null) : base(scope, id, props)
    {
        var instance = new Instance(this, "rInstance", new InstanceProps {
            Vpc = new Vpc(this, "rVpc"),
            InstanceType = new InstanceType(InstanceClass.T3),
            MachineImage = MachineImage.LatestAmazonLinux()
        });
        var cfnIns = (CfnInstance)instance.Node.DefaultChild;
        cfnIns.AddPropertyOverride("DisableApiTermination", true);
        NagSuppressions.AddResourceSuppressions(instance, new [] { new NagPackSuppression {
            Id = "AwsSolutions-EC29",
            Reason = "Remediated through property override."
        } });
    }
}

