import software.amazon.awscdk.services.ec2.Instance;
import software.amazon.awscdk.services.ec2.InstanceType;
import software.amazon.awscdk.services.ec2.InstanceClass;
import software.amazon.awscdk.services.ec2.MachineImage;
import software.amazon.awscdk.services.ec2.Vpc;
import software.amazon.awscdk.services.ec2.CfnInstance;
import software.amazon.awscdk.Stack;
import software.amazon.awscdk.StackProps;
import software.constructs.Construct;
import io.github.cdklabs.cdknag.NagSuppressions;


public class CdkTestStack extends Stack {
    public CdkTestStack(Construct scope, String id) {
        this(scope, id, null);
    }

    public CdkTestStack(Construct scope, String id, StackProps props) {
        super(scope, id, props);
        Instance instance = Instance.Builder.create(this, "rInstance")
                .vpc(new Vpc(this, "rVpc"))
                .instanceType(new InstanceType(InstanceClass.T3))
                .machineImage(MachineImage.latestAmazonLinux())
                .build();
        CfnInstance cfnIns = (CfnInstance)instance.getNode().getDefaultChild();
        cfnIns.addPropertyOverride("DisableApiTermination", true);
        NagSuppressions.addResourceSuppressions(instance, List.of(NagPackSuppression.builder()
                .id("AwsSolutions-EC29")
                .reason("Remediated through property override.")
                .build()));
    }
}

