using Cdklabs.CdkNag;
using Amazon.CDK;
using Constructs;

class CdkTestStack : Stack
{
    public CdkTestStack(Construct scope, string id, StackProps? props=null) : base(scope, id, props)
    {
        new CfnInclude(this, "Template", new CfnIncludeProps {
            TemplateFile = "my-template.json"
        });
        // Add any additional suppressions
        NagSuppressions.AddResourceSuppressionsByPath(this, "/CdkNagDemo/Template/myPolicy", new [] { new NagPackSuppression {
